+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    static final String NAME_REQUIRED = "Name is required";
+    static final String EMAIL_INVALID = "Enter a valid e-mail address";
+    static final String CONTACT_REQUIRED = "Give an e-mail address or a phone number";
+    static final String MESSAGE_REQUIRED = "Message is required";
+    static final String MESSAGE_TOO_LONG = "Message must be at most " + MAX_MESSAGE_LENGTH
+            + " characters";
+    static final String SENT = "Message sent";
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile(EmailValidator.PATTERN);
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> sent = new Grid<>();
+
+    private final List<TextFieldBase<?, String>> fields = List.<TextFieldBase<?, String>>of(name,
+            email, phone, message);
+
+    private Notification lastNotification;
+
+    public ContactView() {
+        setSizeFull();
+
+        fields.forEach(field -> {
+            // The server needs to know what is in a field as it is typed, both
+            // to re-enable Send and to notice that there is something to lose.
+            field.setValueChangeMode(ValueChangeMode.EAGER);
+            // Validation happens on Send, and its messages are ours alone.
+            field.setManualValidation(true);
+            field.addValueChangeListener(event -> send.setEnabled(true));
+        });
+        message.setMinRows(4);
+
+        send.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        send.addClickListener(event -> trySend());
+        send.addClickShortcut(Key.ENTER);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+        form.setMaxWidth("40em");
+
+        sent.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        sent.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        sent.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        sent.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        sent.setAllRowsVisible(true);
+        refreshGrid();
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class), form, send,
+                new H2("Sent messages"), sent);
+    }
+
+    private void trySend() {
+        if (!send.isEnabled()) {
+            return;
+        }
+        clearErrors();
+        if (lastNotification != null) {
+            // The word on the last send says nothing about this one.
+            lastNotification.close();
+            lastNotification = null;
+        }
+
+        boolean valid = true;
+        if (name.getValue().isBlank()) {
+            fail(name, NAME_REQUIRED);
+            valid = false;
+        }
+        String address = email.getValue().trim();
+        if (!address.isEmpty() && !EMAIL_PATTERN.matcher(address).matches()) {
+            fail(email, EMAIL_INVALID);
+            valid = false;
+        } else if (address.isEmpty() && phone.getValue().isBlank()) {
+            fail(email, CONTACT_REQUIRED);
+            valid = false;
+        }
+        if (message.getValue().isBlank()) {
+            fail(message, MESSAGE_REQUIRED);
+            valid = false;
+        } else if (message.getValue().length() > MAX_MESSAGE_LENGTH) {
+            fail(message, MESSAGE_TOO_LONG);
+            valid = false;
+        }
+        if (!valid) {
+            return;
+        }
+
+        MessageStore.current().add(new ContactMessage(name.getValue().trim(), address,
+                phone.getValue().trim(), message.getValue()));
+        refreshGrid();
+
+        lastNotification = Notification.show(SENT);
+        lastNotification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+
+        // Clearing the fields fires value changes, which re-enable Send, so
+        // disabling it afterwards is what leaves it disabled until the next edit.
+        fields.forEach(TextFieldBase::clear);
+        send.setEnabled(false);
+    }
+
+    private void fail(TextFieldBase<?, String> field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        fields.forEach(field -> {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        });
+    }
+
+    private void refreshGrid() {
+        sent.setItems(MessageStore.current().messages());
+    }
+
+    private boolean hasUnsentInput() {
+        return fields.stream().anyMatch(field -> !field.getValue().isEmpty());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsentInput()) {
+            return;
+        }
+        ContinueNavigationAction action = event.postpone();
+
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Leave without sending?");
+        dialog.add(new Paragraph("The message has not been sent yet."));
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        // Cancelling, rather than just dropping the postponed action, is what
+        // tells the browser that its address is still this view's, so that the
+        // next attempt to leave is a navigation again and asks anew.
+        Button keepEditing = new Button("Keep editing", click -> {
+            dialog.close();
+            action.cancel();
+        });
+        keepEditing.addThemeVariants(ButtonVariant.LUMO_PRIMARY);
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR, ButtonVariant.LUMO_TERTIARY);
+        dialog.getFooter().add(keepEditing, discard);
+
+        dialog.open();
+    }
