+package com.example;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+
+import org.junit.jupiter.api.Test;
+import com.microsoft.playwright.Locator;
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+/**
+ * The same behaviour as {@link ContactViewTest}, but driven through a real
+ * browser: keystrokes, client side validation and client side routing included.
+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private Locator aboutLink() {
+        return page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About"));
+    }
+
+    private Locator dialogButton(String text) {
+        return page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName(text));
+    }
+
+    private void fillValid() {
+        name().setValue("Ada");
+        email().setValue("ada@example.com");
+        message().setValue("Hello there");
+    }
+
+    @Test
+    void contactView_showsHeadingLinkFormAndEnabledSend() {
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(aboutLink()).isVisible();
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void emptyForm_send_showsErrorsAndSendsNothing() {
+        send().click();
+
+        name().assertErrorMessage("Name is required");
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertErrorMessage("Message is required");
+        name().assertInvalid();
+        email().assertInvalid();
+        message().assertInvalid();
+        phone().assertValid();
+
+        assertThat(page.locator("vaadin-notification-card")).hasCount(0);
+        GridElement.get(page).assertEmpty();
+        send().assertEnabled();
+    }
+
+    @Test
+    void invalidEmail_send_showsErrorAndKeepsInput() {
+        name().setValue("Ada");
+        email().setValue("not-an-address");
+        message().setValue("Hello there");
+        send().click();
+
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValue("Ada");
+        message().assertValue("Hello there");
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void tooLongMessage_send_showsError() {
+        name().setValue("Ada");
+        phone().setValue("555 1234");
+        message().setValue("x".repeat(501));
+        send().click();
+
+        message().assertErrorMessage("Message must be at most 500 characters");
+        GridElement.get(page).assertEmpty();
+    }
+
+    @Test
+    void validForm_send_notifiesListsClearsAndDisablesSend() {
+        fillValid();
+        send().click();
+
+        assertThat(page.locator("vaadin-notification-card")).containsText("Message sent");
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        grid.assertCellContent(0, 0, "Ada");
+        grid.assertCellContent(0, 1, "Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("Grace");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterKey_sends() {
+        fillValid();
+        message().getInputLocator().press("Enter");
+
+        GridElement.get(page).assertRowCount(1);
+        message().assertValue("");
+    }
+
+    @Test
+    void aboutLink_navigatesWithoutReloadingWhenFormIsEmpty() {
+        page.evaluate("window.__notReloaded = true");
+        aboutLink().click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertThat(dialogButton("Keep editing")).hasCount(0);
+        assertEquals(Boolean.TRUE, page.evaluate("window.__notReloaded"),
+                "client side navigation, no page reload");
+    }
+
+    @Test
+    void dirtyForm_asksBeforeLeaving() {
+        name().setValue("Ada");
+        aboutLink().click();
+
+        new DialogElement(page).assertOpen();
+        dialogButton("Keep editing").click();
+
+        assertThat(dialogButton("Keep editing")).hasCount(0);
+        assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("Ada");
+
+        aboutLink().click();
+        new DialogElement(page).assertOpen();
+        dialogButton("Discard").click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+
+    @Test
+    void sentMessages_surviveLeavingAndComingBack() {
+        fillValid();
+        send().click();
+        GridElement.get(page).assertRowCount(1);
+
+        aboutLink().click();
+        assertThat(page.locator("h1")).hasText("About");
+        page.goBack();
+
+        assertThat(page.locator("h1")).hasText("Contact");
+        GridElement.get(page).assertRowCount(1);
+        GridElement.get(page).assertCellContent(0, 0, "Ada");
+    }
+}
