+package com.example;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertNotNull;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.example.contact.AboutView;
+import com.example.contact.ContactView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return find(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return find(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return find(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea message() {
+        return find(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button send() {
+        return find(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Object> grid() {
+        return find(Grid.class).single();
+    }
+
+    private List<Notification> notifications() {
+        return find(Notification.class).all();
+    }
+
+    private void fillValid() {
+        test(name()).setValue("Ada");
+        test(email()).setValue("ada@example.com");
+        test(message()).setValue("Hello there");
+    }
+
+    @Test
+    void contactView_showsHeadingLinkFormAndEnabledSend() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", find(H1.class).single().getText());
+        assertEquals("About", find(RouterLink.class).withText("About").single().getText());
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled(), "Send is enabled on the untouched form");
+        assertNotNull(grid());
+    }
+
+    @Test
+    void emptyForm_send_reportsNameContactAndMessage() {
+        navigate(ContactView.class);
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+
+        assertTrue(notifications().isEmpty(), "nothing is sent");
+        assertEquals(0, test(grid()).size());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void invalidEmail_send_reportsInvalidAddressAndKeepsInput() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("not-an-address");
+        test(message()).setValue("Hello there");
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(message().isInvalid());
+
+        assertEquals("Ada", name().getValue());
+        assertEquals("not-an-address", email().getValue());
+        assertEquals("Hello there", message().getValue());
+        assertEquals(0, test(grid()).size());
+        assertTrue(notifications().isEmpty());
+    }
+
+    @Test
+    void phoneAlone_isEnough() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(phone()).setValue("+358 40 123 4567");
+        test(message()).setValue("Call me");
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void emailAlone_isEnough() {
+        navigate(ContactView.class);
+        fillValid();
+        test(send()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessage_isRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(phone()).setValue("123");
+        test(message()).setValue("x".repeat(501));
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals(0, test(grid()).size());
+
+        test(message()).setValue("x".repeat(500));
+        test(send()).click();
+        assertFalse(message().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validForm_send_notifiesListsClearsAndDisablesSend() {
+        navigate(ContactView.class);
+        fillValid();
+        test(send()).click();
+
+        assertTrue(notifications().stream()
+                .anyMatch(notification -> test(notification).getText().contains("Message sent")),
+                "a notification about the sent message");
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+        assertEquals("Hello there", test(grid()).getCellText(0, 1));
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+
+        assertFalse(send().isEnabled(), "Send is disabled right after sending");
+
+        test(name()).setValue("Grace");
+        assertTrue(send().isEnabled(), "Send is enabled again after an edit");
+    }
+
+    @Test
+    void failedSend_afterASuccessfulOne_saysNothingAndAddsNoRow() {
+        navigate(ContactView.class);
+        fillValid();
+        test(send()).click();
+
+        test(message()).setValue("Second one");
+        test(send()).click();
+
+        assertTrue(email().isInvalid(), "the cleared contact details are missing");
+        assertEquals(1, test(grid()).size());
+        assertTrue(notifications().stream()
+                .noneMatch(notification -> test(notification).isUsable()),
+                "no notification is left saying the message was sent");
+    }
+
+    @Test
+    void disabledSend_ignoresTheEnterKey() {
+        navigate(ContactView.class);
+        fillValid();
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        fireShortcut(Key.ENTER);
+
+        assertFalse(name().isInvalid(), "an untouched form is not marked up with errors");
+        assertFalse(email().isInvalid());
+        assertFalse(message().isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void newestMessage_isFirst() {
+        navigate(ContactView.class);
+        fillValid();
+        test(send()).click();
+        test(name()).setValue("Grace");
+        test(phone()).setValue("555");
+        test(message()).setValue("Second one");
+        test(send()).click();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Grace", test(grid()).getCellText(0, 0));
+        assertEquals("Ada", test(grid()).getCellText(1, 0));
+    }
+
+    @Test
+    void sentMessages_surviveLeavingAndComingBack() {
+        navigate(ContactView.class);
+        fillValid();
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("Ada", test(grid()).getCellText(0, 0));
+    }
+
+    @Test
+    void enterKey_sends() {
+        navigate(ContactView.class);
+        fillValid();
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("", message().getValue());
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        navigate(ContactView.class);
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertFalse(find(Dialog.class).exists(), "no dialog for an empty form");
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void filledForm_keepEditing_staysOnTheForm() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        UI.getCurrent().navigate(AboutView.class);
+
+        Dialog dialog = find(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        find(Button.class).withText("Keep editing").single().click();
+
+        assertFalse(find(Dialog.class).exists(), "the dialog is gone");
+        assertTrue(getCurrentView() instanceof ContactView, "still on the contact view");
+        assertEquals("Ada", name().getValue());
+    }
+
+    @Test
+    void filledForm_keepEditing_asksAgainOnTheNextAttempt() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        UI.getCurrent().navigate(AboutView.class);
+        find(Button.class).withText("Keep editing").single().click();
+
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue(find(Dialog.class).single().isOpened(), "asked a second time");
+        find(Button.class).withText("Discard").single().click();
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void filledForm_discard_leaves() {
+        navigate(ContactView.class);
+        test(message()).setValue("half written");
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue(getCurrentView() instanceof ContactView, "navigation is postponed");
+        find(Button.class).withText("Discard").single().click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+        assertEquals("About", find(H1.class).single().getText());
+    }
+
+    @Test
+    void aboutLink_asksBeforeLosingInput() {
+        navigate(ContactView.class);
+        test(phone()).setValue("555");
+        test(find(RouterLink.class).withText("About").single()).click();
+
+        assertTrue(getCurrentView() instanceof ContactView);
+        find(Button.class).withText("Discard").single().click();
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void aboutView_showsHeading() {
+        navigate(AboutView.class);
+        assertEquals("About", find(H1.class).single().getText());
+    }
+}
